const { GeminiRotator } = require('/home/node/scripts/gemini-rotation.js');
const body = $input.first().json.body;
const fileBuffer = await $http.request({ method: 'GET', url: body.fileUrl, encoding: 'arraybuffer' });
const base64 = Buffer.from(fileBuffer).toString('base64');
const mime = body.mimeType || 'application/pdf';
const rotator = new GeminiRotator(process.env.GEMINI_API_KEYS.split(','));
const res = await $http.request({
  method: 'POST',
  url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${process.env.GEMINI_API_KEYS.split(',')[0]}`,
  headers: { 'Content-Type': 'application/json' },
  body: {
    contents: [{ parts: [{ text: 'Extract all text from this CV/resume. Return only the text.' }, { inlineData: { mimeType: mime, data: base64 } }] }],
    generationConfig: { temperature: 0.2 },
  },
});
const extractedText = res.candidates?.[0]?.content?.parts?.[0]?.text || '';
return [{ json: { extractedText, customerId: body.customerId, filename: body.filename || 'uploaded_cv' } }];

const { GeminiRotator } = require('/home/node/scripts/gemini-rotation.js');
const { saveCvAnalysis } = require('/home/node/scripts/cvpro-helpers.js');
const { extractedText, customerId, filename } = $input.first().json;
const systemPrompt = `You are ATS expert for UAE/Gulf market. Return JSON: ats_score, formatting_score, keyword_score, readability_score, achievements_score, grammar_score, linkedin_compatibility_score, uae_gulf_score (0-100), weaknesses[], improvement_suggestions[], sales_pitch, personalized_offer.`;
const rotator = new GeminiRotator(process.env.GEMINI_API_KEYS.split(','));
const analysis = await rotator.callJSON(extractedText.substring(0, 6000), systemPrompt);
const record = await saveCvAnalysis($http, customerId, extractedText, analysis, filename);
return [{ json: { analysis, analysisId: record.id } }];
